<?php
require_once "db.php"; require_login();
$uid = (int)$_SESSION["user_id"];
$stmt = $conn->prepare("SELECT COUNT(*) n FROM emergency_contacts WHERE user_id=?"); $stmt->bind_param("i",$uid); $stmt->execute(); $contacts=(int)$stmt->get_result()->fetch_assoc()["n"];
$stmt = $conn->prepare("SELECT COUNT(*) n FROM alerts WHERE user_id=?"); $stmt->bind_param("i",$uid); $stmt->execute(); $alerts=(int)$stmt->get_result()->fetch_assoc()["n"];
$stmt = $conn->prepare("SELECT COUNT(*) n FROM alerts WHERE user_id=? AND status='Triggered'"); $stmt->bind_param("i",$uid); $stmt->execute(); $active=(int)$stmt->get_result()->fetch_assoc()["n"];
$stmt = $conn->prepare("SELECT alert_type,location_text,status,alert_time FROM alerts WHERE user_id=? ORDER BY id DESC LIMIT 5"); $stmt->bind_param("i",$uid); $stmt->execute(); $recent=$stmt->get_result();
?>
